	if count > math.MaxInt32 {
		if c.Worker != nil {
			c.Refused = true
			c.Worker.refused = true
		}
		return false
	}
	if count == 0 {
		return true
	}
	if c.Worker != nil {
		return true
	}
	p := c.Alloc(int64(count)*size, align)
	if p == nil {
		return false
	}
	h.Ref = int64(uintptr(p) - uintptr(unsafe.Pointer(h)))
