type PairBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *PairBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(Pair{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	PairReset((*Pair)(p))
	return true
}
func (b *PairBuilder) GetRoot() *Pair {
	if b.Arena.Locked {
		return nil
	}
	return (*Pair)(b.Arena.At(b.root))
}
func (b *PairBuilder) AsConst() *Pair {
	if len(b.region) == 0 {
		return nil
	}
	return (*Pair)(unsafe.Pointer(&b.region[0]))
}
func (b *PairBuilder) Region() []byte { return b.region }
func (b *PairBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), PairTableType(), &b.Arena)
}
func (b *PairBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), PairTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *PairBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), PairTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *PairBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

// FlagReset restores Flag's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func FlagReset(value *Flag) {
	value.Name = 0
	value.On = false
}

func FlagMeasureBody(value *Flag, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !FlagSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func FlagSaveBody(w *TableWriter, value *Flag) bool {
	if !FlagSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
func FlagSaveBodyFields(w *TableWriter, value *Flag) bool {
	{
		if value.Name != 0 {
			if ref := w.Ids.refAtHit(167, 0xc4bcadba8e631b86); !w.headerPair(ref, 17) {
				w.headerRest(ref, 17)
			}
			if value.Name == 0 {
				if !w.putLebPair(0) {
					w.putLebWide(0)
				}
			} else {
				index, ok := w.Ids.Numbering.Index(&value.Name)
				if !ok {
					return false
				}
				if !w.putLebPair(index) {
					w.putLebWide(index)
				}
			}
		}
	}
	{
		if value.On != false {
			if ref := w.Ids.refAtHit(7, 0x08b05807b5566370); !w.headerPair(ref, 1) {
				w.headerRest(ref, 1)
			}
			if value.On {
				w.Put8(1)
			} else {
				w.Put8(0)
			}
		}
	}
	return !w.Overflow && !w.Ids.Overflow
}

func FlagLoadBody(r *TableReader, value *Flag) bool {
	FlagReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		switch fieldID {
		case 0xc4bcadba8e631b86: // name
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.Name, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0x08b05807b5566370: // on
			if kind != 1 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			if !r.Has(1) {
				r.Report.Malformed = true
				return false
			}
			value.On = r.Get8() != 0
		case 0xffffffffffffffff:
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

