func ImageLoadBuilder(b *ImageBuilder, wire []byte, report *TableReport) bool {
	return tableBuilderLoad(unsafe.Pointer(b.GetRoot()), b.root, &b.Main, wire, ImageTableType(), ImageTableType().NodeType, 1, report)
}

type ImageBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *ImageBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(Image{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	ImageReset((*Image)(p))
	return true
}
func (b *ImageBuilder) GetRoot() *Image {
	if b.Arena.Locked {
		return nil
	}
	return (*Image)(b.Arena.At(b.root))
}
func (b *ImageBuilder) AsConst() *Image {
	if len(b.region) == 0 {
		return nil
	}
	return (*Image)(unsafe.Pointer(&b.region[0]))
}
func (b *ImageBuilder) Region() []byte { return b.region }
func (b *ImageBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), ImageTableType(), &b.Arena)
}
func (b *ImageBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), ImageTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *ImageBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), ImageTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *ImageBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

// TokensReset restores Tokens's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func TokensReset(value *Tokens) {
	value.Input = 0
	value.CacheRead = 0
	value.CacheWrite = 0
	value.Output = 0
	value.Reasoning = 0
	value.Requests = 0
	value.MaxPrompt = 0
}

func TokensMeasureBody(value *Tokens, ids *TableIds) int64 {
	bytes := int64(1)
	if value.Input != 0 {
		bytes += tableLebBytes(ids.refAtHit(25, 0x1ebbae8f5810b65b)) + 1 + 8
	} // input
	if value.CacheRead != 0 {
		bytes += tableLebBytes(ids.refAtHit(100, 0x779748cd7970e246)) + 1 + 8
	} // cache_read
	if value.CacheWrite != 0 {
		bytes += tableLebBytes(ids.refAtHit(44, 0x313c6440b18aae09)) + 1 + 8
	} // cache_write
	if value.Output != 0 {
		bytes += tableLebBytes(ids.refAtHit(18, 0x150f53f8651b4384)) + 1 + 8
	} // output
	if value.Reasoning != 0 {
		bytes += tableLebBytes(ids.refAtHit(126, 0x938f9c45fb249647)) + 1 + 8
	} // reasoning
	if value.Requests != 0 {
		bytes += tableLebBytes(ids.refAtHit(96, 0x7166d3e80f26d1f3)) + 1 + 8
	} // requests
	if value.MaxPrompt != 0 {
		bytes += tableLebBytes(ids.refAtHit(112, 0x832da51eba5c8b80)) + 1 + 8
	} // max_prompt
	if ids.Overflow {
		return -1
	}
	return bytes
}

func TokensMeasure(value *Tokens) int64 {
	var ids TableIds
	body := TokensMeasureBody(value, &ids)
	if body < 0 || ids.Overflow {
		return -1
	}
	return 1 + body + int64(ids.Count)*8 + 8
}

func TokensMeasureReason(value *Tokens) (int64, error) {
	size := TokensMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
