// UsageReset restores Usage's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func UsageReset(value *Usage) {
	value.Billing = 0
	value.ReceiptVersion = 0
	value.RawUsage = 0
	value.Wall = 0
	value.Budget = 0
	TokensReset(&value.Tokens)
	value.Model = 0
	value.ActualUsd = 0
	value.ActualBy = 0
	value.WaitS = 0
	value.RunS = 0
	value.PriceRoute = 0
	value.Prices = 0
	value.PredictedUsd = 0
	value.LongContext = false
	value.Unpriced = 0
}

