func TotalLoadMeasure(wire []byte) int64 {
	n, _, _ := tableRegionMeasure(wire, TotalTableType(), TotalTableType().NodeType, 2)
	return n
}
func TotalLoadMeasureReason(wire []byte) (int64, error) {
	size, _, _, reason := tableRegionMeasureReason(wire, TotalTableType(), TotalTableType().NodeType, 2)
	return size, tableRefuseError(reason)
}
func TotalLoad(region, wire []byte, report *TableReport) *Total {
	return (*Total)(tableRegionLoad(region, wire, TotalTableType(), TotalTableType().NodeType, 2, report))
}
func TotalMeasure(value *Total, context ...TableWriteContext) int64 {
	arena, allocator := tableWriteOptions(context)
	return tableRegionSave(unsafe.Pointer(value), TotalTableType(), nil, true, arena, allocator)
}
func TotalMeasureReason(value *Total, context ...TableWriteContext) (int64, error) {
	arena, allocator := tableWriteOptions(context)
	size, reason := tableRegionSaveReason(unsafe.Pointer(value), TotalTableType(), nil, true, arena, allocator)
	return size, tableRefuseError(reason)
}
func TotalSave(value *Total, buffer []byte, context ...TableWriteContext) int64 {
	arena, allocator := tableWriteOptions(context)
	return tableRegionSave(unsafe.Pointer(value), TotalTableType(), buffer, false, arena, allocator)
}
func TotalLoadBuilder(b *TotalBuilder, wire []byte, report *TableReport) bool {
	return tableBuilderLoad(unsafe.Pointer(b.GetRoot()), b.root, &b.Main, wire, TotalTableType(), TotalTableType().NodeType, 2, report)
}

type TotalBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *TotalBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(Total{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	TotalReset((*Total)(p))
	return true
}
func (b *TotalBuilder) GetRoot() *Total {
	if b.Arena.Locked {
		return nil
	}
	return (*Total)(b.Arena.At(b.root))
}
func (b *TotalBuilder) AsConst() *Total {
	if len(b.region) == 0 {
		return nil
	}
	return (*Total)(unsafe.Pointer(&b.region[0]))
}
func (b *TotalBuilder) Region() []byte { return b.region }
func (b *TotalBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), TotalTableType(), &b.Arena)
}
func (b *TotalBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), TotalTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *TotalBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), TotalTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *TotalBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

// ConsumerReset restores Consumer's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func ConsumerReset(value *Consumer) {
	value.Kind = 0
	value.Card = 0
	value.Attempt = 0
	value.Take = 0
	value.Gen = 0
	value.Who = 0
	value.Route = 0
	value.Model = 0
	value.Tier = 0
	value.End = 0
	value.At = 0
	value.Key = 0
	UsageReset(&value.Usage)
	value.Cap = 0
	value.Overrun = 0
}

func ConsumerMeasureBody(value *Consumer, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !ConsumerSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

