func CardCostViewLoadBody(r *TableReader, value *CardCostView) bool {
	CardCostViewReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		switch fieldID {
		case 0x97842f69f4f0ba0e: // consumers
			if kind != 14 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if len(sub.Buffer) >= 2 {
				header := sub
				header.Buffer = r.Buffer[r.Offset-int64(len(sub.Buffer)):]
				elemKind := header.Get8()
				count, ok := header.Leb()
				sub.Offset = header.Offset
				if !ok {
					r.Report.Malformed = true
					break
				}
				if elemKind != 13 {
					if !tableKindWidens(elemKind, 13) {
						r.Report.KindMismatch++
						break
					}
					r.Report.Widened++
				}
				slot := (*tableContainer)(unsafe.Pointer(&value.Consumers))
				if !tableContainerFill(&sub.Nodes.Carve, slot, count, int64(unsafe.Sizeof(*new(ConsumerRow))), 8) {
					if sub.Nodes.Carve.Refused {
						r.Take(sub)
						return false
					}
					r.Report.Malformed = true
					break
				}
				slot.Count = 0
				for i := uint64(0); i < count; i++ {
					p := (*ConsumerRow)(tableContainerFillAt(&sub.Nodes.Carve, slot, int32(i), int64(unsafe.Sizeof(*new(ConsumerRow)))))
					if p == nil {
						r.Report.Malformed = true
						break
					}
					landed := false
					for once := true; once; once = false {
						elem, ok := sub.Body()
						if !ok {
							r.Report.Malformed = true
							break
						}
						ConsumerLoadBody(&elem, p)
						sub.Take(elem)
						if sub.Nodes.Carve.Refused {
							r.Nodes.Carve = sub.Nodes.Carve
							return false
						}
						if elem.Offset != int64(len(elem.Buffer)) {
							r.Report.Malformed = true
							ConsumerReset(p)
						}
						landed = true
					}
					if !landed {
						if sub.Nodes.Carve.Worker != nil {
							tableContainerErase(sub.Nodes.Carve.Worker.Arena, slot, unsafe.Pointer(p), int64(unsafe.Sizeof(*p)))
						}
						break
					}
					if sub.Nodes.Carve.Worker == nil {
						slot.Count++
					}
				}
				r.Take(sub)
				if r.Nodes.Carve.Refused {
					return false
				}
			}
		case 0x2dcede7d543a4ffd: // total
			if kind != 13 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			TotalLoadBody(&sub, &value.Total)
			r.Take(sub)
			if r.Nodes.Carve.Refused {
				return false
			}
			if sub.Offset != int64(len(sub.Buffer)) {
				r.Report.Malformed = true
				TotalReset(&value.Total)
			}
		case 0xf5b9f7190cc182e3: // cut
			if kind != 5 {
				if tableKindWidens(kind, 5) {
					if !r.Has(tableKindBytes(kind)) {
						r.Report.Malformed = true
						return false
					}
					{
						v := r.Signed(kind)
						value.Cut = int64(v)
					}
					r.Report.Widened++
					break
				}
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			if !r.Has(8) {
				r.Report.Malformed = true
				return false
			}
			{
				v := int64(r.Get64())
				value.Cut = int64(v)
			}
		case 0x57fbf1dca08b802a: // carried_usd
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.CarriedUsd, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0xb4348854e0c0cb3e: // carried_from
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.CarriedFrom, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0x31a2d36232f8a0df: // carried_to
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.CarriedTo, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0xffffffffffffffff:
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

