// SnapshotCountsReset restores SnapshotCounts's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func SnapshotCountsReset(value *SnapshotCounts) {
	value.Keys = 0
	value.Cards = 0
}

func SnapshotCountsMeasureBody(value *SnapshotCounts, ids *TableIds) int64 {
	bytes := int64(1)
	if value.Keys != 0 {
		bytes += tableLebBytes(ids.refAtHit(72, 0x581987d75cbd3e2d)) + 1 + 8
	} // keys
	if value.Cards != 0 {
		bytes += tableLebBytes(ids.refAtHit(150, 0xaf9dac3b097689c4)) + 1 + 8
	} // cards
	if ids.Overflow {
		return -1
	}
	return bytes
}

func SnapshotCountsMeasure(value *SnapshotCounts) int64 {
	var ids TableIds
	body := SnapshotCountsMeasureBody(value, &ids)
	if body < 0 || ids.Overflow {
		return -1
	}
	return 1 + body + int64(ids.Count)*8 + 8
}

func SnapshotCountsMeasureReason(value *SnapshotCounts) (int64, error) {
	size := SnapshotCountsMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
