type SprintStateBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *SprintStateBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(SprintState{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	SprintStateReset((*SprintState)(p))
	return true
}
func (b *SprintStateBuilder) GetRoot() *SprintState {
	if b.Arena.Locked {
		return nil
	}
	return (*SprintState)(b.Arena.At(b.root))
}
func (b *SprintStateBuilder) AsConst() *SprintState {
	if len(b.region) == 0 {
		return nil
	}
	return (*SprintState)(unsafe.Pointer(&b.region[0]))
}
func (b *SprintStateBuilder) Region() []byte { return b.region }
func (b *SprintStateBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), SprintStateTableType(), &b.Arena)
}
func (b *SprintStateBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), SprintStateTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *SprintStateBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), SprintStateTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *SprintStateBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}
