type CellBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *CellBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(Cell{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	CellReset((*Cell)(p))
	return true
}
func (b *CellBuilder) GetRoot() *Cell {
	if b.Arena.Locked {
		return nil
	}
	return (*Cell)(b.Arena.At(b.root))
}
func (b *CellBuilder) AsConst() *Cell {
	if len(b.region) == 0 {
		return nil
	}
	return (*Cell)(unsafe.Pointer(&b.region[0]))
}
func (b *CellBuilder) Region() []byte { return b.region }
