type NTableBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *NTableBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(NTable{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	NTableReset((*NTable)(p))
	return true
}
func (b *NTableBuilder) GetRoot() *NTable {
	if b.Arena.Locked {
		return nil
	}
	return (*NTable)(b.Arena.At(b.root))
}
func (b *NTableBuilder) AsConst() *NTable {
	if len(b.region) == 0 {
		return nil
	}
	return (*NTable)(unsafe.Pointer(&b.region[0]))
}
func (b *NTableBuilder) Region() []byte { return b.region }
func (b *NTableBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), NTableTableType(), &b.Arena)
}
func (b *NTableBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), NTableTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *NTableBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), NTableTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *NTableBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}
