// FieldChangeReset restores FieldChange's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func FieldChangeReset(value *FieldChange) {
	value.Name = 0
	value.Before = 0
	value.After = 0
	value.BeforeBytes = 0
	value.BeforeSha1 = 0
	value.AfterBytes = 0
	value.AfterSha1 = 0
}

