// OpEntryReset restores OpEntry's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func OpEntryReset(value *OpEntry) {
	value.Key = 0
	value.Body = 0
	ReceiptReset(&value.Receipt)
}

func OpEntryMeasureBody(value *OpEntry, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !OpEntrySaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func OpEntrySaveBody(w *TableWriter, value *OpEntry) bool {
	if !OpEntrySaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
func OpEntrySaveBodyFields(w *TableWriter, value *OpEntry) bool {
	{
		if value.Key != 0 {
			if ref := w.Ids.refAtHit(56, 0x3dc94a19365b10ec); !w.headerPair(ref, 17) {
				w.headerRest(ref, 17)
			}
			if value.Key == 0 {
				if !w.putLebPair(0) {
					w.putLebWide(0)
				}
			} else {
				index, ok := w.Ids.Numbering.Index(&value.Key)
				if !ok {
					return false
				}
				if !w.putLebPair(index) {
					w.putLebWide(index)
				}
			}
		}
	}
	{
		if value.Body != 0 {
			if ref := w.Ids.refAtHit(174, 0xcd4de79bc6c93295); !w.headerPair(ref, 17) {
				w.headerRest(ref, 17)
			}
			if value.Body == 0 {
				if !w.putLebPair(0) {
					w.putLebWide(0)
				}
			} else {
				index, ok := w.Ids.Numbering.Index(&value.Body)
				if !ok {
					return false
				}
				if !w.putLebPair(index) {
					w.putLebWide(index)
				}
			}
		}
	}
	{
		mark := w.Ids.Count
		ref := w.Ids.refAtHit(209, 0xf8f39921c835bf03)
		start := w.Ids.Count
		n := ReceiptMeasureBody(&value.Receipt, w.Ids)
		if n < 0 || w.Ids.Overflow {
			return false
		}
		if n > 1 {
			if w.Measuring {
				w.Advance(tableLebBytes(ref) + 1 + tableLebBytes(uint64(n)) + n)
			} else {
				w.Ids.Truncate(start)
				if !w.headerPair(ref, 13) {
					w.headerRest(ref, 13)
				}
				if !w.putLebPair(uint64(n)) {
					w.putLebWide(uint64(n))
				}
				if !ReceiptSaveBody(w, &value.Receipt) {
					return false
				}
			}
		} else {
			w.Ids.Truncate(mark)
		}
	}
	return !w.Overflow && !w.Ids.Overflow
}

func OpEntryLoadBody(r *TableReader, value *OpEntry) bool {
	OpEntryReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		switch fieldID {
		case 0x3dc94a19365b10ec: // key
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.Key, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0xcd4de79bc6c93295: // body
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.Body, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0xf8f39921c835bf03: // receipt
			if kind != 13 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			ReceiptLoadBody(&sub, &value.Receipt)
			r.Take(sub)
			if r.Nodes.Carve.Refused {
				return false
			}
			if sub.Offset != int64(len(sub.Buffer)) {
				r.Report.Malformed = true
				ReceiptReset(&value.Receipt)
			}
		case 0xffffffffffffffff:
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

