type EpochSnapshotBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *EpochSnapshotBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(EpochSnapshot{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	EpochSnapshotReset((*EpochSnapshot)(p))
	return true
}
func (b *EpochSnapshotBuilder) GetRoot() *EpochSnapshot {
	if b.Arena.Locked {
		return nil
	}
	return (*EpochSnapshot)(b.Arena.At(b.root))
}
func (b *EpochSnapshotBuilder) AsConst() *EpochSnapshot {
	if len(b.region) == 0 {
		return nil
	}
	return (*EpochSnapshot)(unsafe.Pointer(&b.region[0]))
}
func (b *EpochSnapshotBuilder) Region() []byte { return b.region }
func (b *EpochSnapshotBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), EpochSnapshotTableType(), &b.Arena)
}
func (b *EpochSnapshotBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), EpochSnapshotTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *EpochSnapshotBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), EpochSnapshotTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *EpochSnapshotBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}
