type TableSnapshotBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *TableSnapshotBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(TableSnapshot{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	TableSnapshotReset((*TableSnapshot)(p))
	return true
}
func (b *TableSnapshotBuilder) GetRoot() *TableSnapshot {
	if b.Arena.Locked {
		return nil
	}
	return (*TableSnapshot)(b.Arena.At(b.root))
}
func (b *TableSnapshotBuilder) AsConst() *TableSnapshot {
	if len(b.region) == 0 {
		return nil
	}
	return (*TableSnapshot)(unsafe.Pointer(&b.region[0]))
}
func (b *TableSnapshotBuilder) Region() []byte { return b.region }
func (b *TableSnapshotBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), TableSnapshotTableType(), &b.Arena)
}
func (b *TableSnapshotBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), TableSnapshotTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *TableSnapshotBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), TableSnapshotTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *TableSnapshotBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}
