// TableEntryReset restores TableEntry's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func TableEntryReset(value *TableEntry) {
	value.Name = 0
	TableSnapshotReset(&value.TableSnapshot)
}

func TableEntryMeasureBody(value *TableEntry, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !TableEntrySaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func TableEntrySaveBody(w *TableWriter, value *TableEntry) bool {
	if !TableEntrySaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
func TableEntrySaveBodyFields(w *TableWriter, value *TableEntry) bool {
	{
		if value.Name != 0 {
			if ref := w.Ids.refAtHit(167, 0xc4bcadba8e631b86); !w.headerPair(ref, 17) {
				w.headerRest(ref, 17)
			}
			if value.Name == 0 {
				if !w.putLebPair(0) {
					w.putLebWide(0)
				}
			} else {
				index, ok := w.Ids.Numbering.Index(&value.Name)
				if !ok {
					return false
				}
				if !w.putLebPair(index) {
					w.putLebWide(index)
				}
			}
		}
	}
	{
		mark := w.Ids.Count
		ref := w.Ids.refAtHit(94, 0x6ff7521170c0e634)
		start := w.Ids.Count
		n := TableSnapshotMeasureBody(&value.TableSnapshot, w.Ids)
		if n < 0 || w.Ids.Overflow {
			return false
		}
		if n > 1 {
			if w.Measuring {
				w.Advance(tableLebBytes(ref) + 1 + tableLebBytes(uint64(n)) + n)
			} else {
				w.Ids.Truncate(start)
				if !w.headerPair(ref, 13) {
					w.headerRest(ref, 13)
				}
				if !w.putLebPair(uint64(n)) {
					w.putLebWide(uint64(n))
				}
				if !TableSnapshotSaveBody(w, &value.TableSnapshot) {
					return false
				}
			}
		} else {
			w.Ids.Truncate(mark)
		}
	}
	return !w.Overflow && !w.Ids.Overflow
}

