type LineSnapshotBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *LineSnapshotBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(LineSnapshot{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	LineSnapshotReset((*LineSnapshot)(p))
	return true
}
func (b *LineSnapshotBuilder) GetRoot() *LineSnapshot {
	if b.Arena.Locked {
		return nil
	}
	return (*LineSnapshot)(b.Arena.At(b.root))
}
func (b *LineSnapshotBuilder) AsConst() *LineSnapshot {
	if len(b.region) == 0 {
		return nil
	}
	return (*LineSnapshot)(unsafe.Pointer(&b.region[0]))
}
func (b *LineSnapshotBuilder) Region() []byte { return b.region }
func (b *LineSnapshotBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), LineSnapshotTableType(), &b.Arena)
}
func (b *LineSnapshotBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), LineSnapshotTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *LineSnapshotBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), LineSnapshotTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *LineSnapshotBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

